ST.xhtml:
(* Only accept a state change after the raw input remains stable for its
   configured debounce time. *)
fbDeb(IN := IN);
IF fbDeb.ET >= SEL(IN, tPresetFall, tPresetRise) THEN
	Q := IN;
END_IF;

(* Note that the down-counter's Q goes high when the counter reaches
   zero. The rising edge trigger will generate a single-cycle pulse at
   that moment. *)
fbCTD(CD := CD, LOAD := LOAD, PV := PV, CV => CV);
fbR_TRIG(CLK := fbCTD.Q, Q => Q);

fbCTU(CU := CU, RESET := RESET, PV := PV, CV => CV);
(* Feed the output of the up-counter to the rising edge trigger. When
   the up-counter reaches its preset value, the rising edge trigger will
   generate a single-cycle pulse. *)
fbR_TRIG(CLK := fbCTU.Q, Q => Q);

(* Track the first cycle of the program run. Q will be TRUE only during
   the first cycle, and X will be set to TRUE afterwards. *)
Q := NOT X;
X := TRUE;

fbTrig(CLK := IN, Q => xFlop);

(* Temporarily disable SA0062 warning. The static analyser incorrectly
   flags the R_TRIG function block output as always FALSE. It does not
   have access to the actual run-time behaviour. *)
{analysis -62}
IF xFlop {analysis +62} THEN
	xFlip := NOT xFlip;
END_IF

(* Use a temporary variable for edge detection in order to avoid reading
   the previous state from the output. *)
Q := xFlip;

(* First, limit the proportional factor to the range [0, 1] because
values outside this range could lead to instability or unexpected
behaviour. Next, calculate the output signal using the limited
proportional factor and the internal state, i.e. the previous output
signal. The current cycle's output becomes the next cycle's feedback. *)
P1 := LIMIT(0, P, 1);
Q1 := (IN * P1) + (Q1 * (1 - P1));
Q  := Q1;

(* Capture the current high-resolution RTC time and determine if the
   input has changed. *)
IF SysTimeRtcHighResGet(tNow) <> CmpErrors.Errors.ERR_OK THEN
	RETURN;
END_IF

xDif := xWas <> IN;

(* Update the previous input and timestamp if a change is detected. *)
IF xDif THEN
	xWas := IN;
	tWas := tNow;
END_IF

(* Update output variables. The change detection flag (Q) and the
   elapsed time since the last change (ET). *)
Q  := xDif;
ET := ULINT_TO_TIME(tNow - tWas);

AU8_TO_U16 := u16XX;

(* Check if the low byte index is within bounds. Do this in an early
   exit manner: return immediately if the index is out of bounds. *)
IF i32LowerBound > i32Lo THEN
	RETURN;
END_IF

IF i32Lo > i32UpperBound THEN
	RETURN;
END_IF

(* Same for the high byte index. *)
IF i32LowerBound > i32Hi THEN
	RETURN;
END_IF

IF i32Hi > i32UpperBound THEN
	RETURN;
END_IF

AU8_TO_U16 := SHL(USINT_TO_UINT(au8[i32Hi]), 8) OR USINT_TO_UINT(au8[i32Lo]);

(* Error band is inclusive of the epsilon value.
Less than or equal to is close enough, rather than strict equality. *)
REPSILONEQ := ABS(rLHS - rRHS) <= rEpsilon;
